            "translate",
            "boolean",
            "not",
            "true",
            "false",
            "null",
            "lang",
            "number",
            "sum",
            "floor",
            "ceiling",
            "round",
            "key",
            "format-number"
        };

        for (final String functionName : functionNames) {
            assertNCName(functionName);
        }
    }

    @Test
    public void returnsTheConsumedTokenImage() throws ParseException {
        final XPathParser parser = new XPathParser(
                new StringReader("first second"));

        assertEquals("first", parser.NCName());
        assertEquals("second", parser.NCName());
    }

    @Test
    public void acceptsNamesWithSurroundingWhitespace() throws ParseException {
        final XPathParser parser = new XPathParser(
                new StringReader("  name \t other"));

        assertEquals("name", parser.NCName());
        assertEquals("other", parser.NCName());
    }

    @Test
    public void rejectsEmptyInput() {
        assertInvalidNCName("");
    }

    @Test
    public void rejectsNumericInput() {
        assertInvalidNCName("123");
    }

    @Test
    public void rejectsPunctuationInput() {
        assertInvalidNCName(".");
        assertInvalidNCName("(");
        assertInvalidNCName("@");
    }
}

